      impl OclaCacheBridge {
          /// Creates a bridge backed by a shared OCLA response cache.
          pub fn new(cache: Arc<ResponseCache>) -> Self {
              Self { cache }
          }

          /// Returns a cached response body for matching request fields.
          pub fn try_cache_hit(
              &self,
              model: &str,
              prompt_hash: &str,
              temp: f32,
              max_tokens: u32,
          ) -> Option<Vec<u8>> {
              self.cache
