                  .map(|response| response.body)
          }

          /// Records a response for matching request fields.
          pub fn record_response(
              &self,
              model: &str,
              prompt_hash: &str,
              temp: f32,
              max_tokens: u32,
              body: &[u8],
              tokens: u64,
          ) {
              self.cache.put(
                  cache_key(model, prompt_hash, temp, max_tokens),
                  CachedResponse {
                      body: body.to_vec(),
                      tokens,
                      created_at: Instant::now(),
                      ttl: Duration::ZERO,
                  },
              );
          }
      }
