impl OclaCacheBridge {
    /// Creates a bridge backed by a shared OCLA response cache.
    pub fn new(cache: Arc<ResponseCache>) -> Self {
        Self { cache }
    }

    /// Returns the cached response, status included, for matching request fields.
    pub fn try_cache_hit(
        &self,
        model: &str,
        prompt_hash: &str,
        temp: f32,
        max_tokens: u32,
    ) -> Option<CachedResponse> {
        self.cache
            .get(&cache_key(model, prompt_hash, temp, max_tokens))
    }

    /// Records the upstream status and body for matching request fields.
    #[allow(clippy::too_many_arguments)]
    pub fn record_response(
        &self,
        model: &str,
        prompt_hash: &str,
        temp: f32,
        max_tokens: u32,
        status: StatusCode,
        body: &[u8],
        tokens: u64,
    ) {
        self.cache.put(
            cache_key(model, prompt_hash, temp, max_tokens),
            CachedResponse {
                status: status.as_u16(),
                body: body.to_vec(),
                tokens,
                created_at: Instant::now(),
                ttl: Duration::ZERO,
            },
        );
    }
}

