#[test]
fn bridge_serves_recorded_response_and_misses_other_requests() {
    let bridge = OclaCacheBridge::new(Arc::new(ResponseCache::new(4, Duration::from_mins(1))));
    let hash = prompt_hash(br#"{"prompt":"hello"}"#);

    assert!(bridge.try_cache_hit("model", &hash, 0.2, 128).is_none());
    bridge.record_response("model", &hash, 0.2, 128, StatusCode::OK, b"answer", 7);

    let hit = bridge
        .try_cache_hit("model", &hash, 0.2, 128)
        .expect("recorded response is served");
    assert_eq!(hit.status, 200);
    assert_eq!(hit.body, b"answer");
    assert!(bridge.try_cache_hit("model", &hash, 0.3, 128).is_none());
    assert!(
        bridge
            .try_cache_hit("other-model", &hash, 0.2, 128)
            .is_none()
    );
}

#[test]
fn bridge_preserves_upstream_error_status() {
    let bridge = OclaCacheBridge::new(Arc::new(ResponseCache::new(4, Duration::from_mins(1))));
    let hash = prompt_hash(br#"{"prompt":"hello"}"#);
    let error = br#"{"error":{"type":"rate_limit_error"}}"#;

    bridge.record_response(
        "model",
        &hash,
        0.0,
        0,
        StatusCode::TOO_MANY_REQUESTS,
        error,
        3,
    );

    let hit = bridge
        .try_cache_hit("model", &hash, 0.0, 0)
        .expect("recorded error is served");
    assert_eq!(hit.status, 429);
    assert_eq!(hit.body, error);
}

#[tokio::test]
async fn replay_response_keeps_cached_status_and_body() {
    let bridge = OclaCacheBridge::new(Arc::new(ResponseCache::new(4, Duration::from_mins(1))));
    let hash = prompt_hash(br#"{"prompt":"hello"}"#);

    for status in [
        StatusCode::OK,
        StatusCode::BAD_REQUEST,
        StatusCode::SERVICE_UNAVAILABLE,
    ] {
        bridge.record_response("model", &hash, 0.0, 0, status, b"payload", 1);
        let cached = bridge
            .try_cache_hit("model", &hash, 0.0, 0)
            .expect("recorded response is served");

        let response = replay_response(cached);
        assert_eq!(response.status(), status);
        let body = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("replayed body is readable");
        assert_eq!(&body[..], b"payload");
    }
}

#[test]
fn replay_response_never_turns_an_invalid_status_into_success() {
    let cached = CachedResponse {
        status: 0,
        body: b"corrupt".to_vec(),
        tokens: 0,
        created_at: Instant::now(),
        ttl: Duration::ZERO,
    };

    assert_eq!(replay_response(cached).status(), StatusCode::BAD_GATEWAY);
}

